"""Dashboard figures built with plotly; tests inspect them as data, nothing is rendered."""
import plotly.express as px
import plotly.graph_objects as go
from plotly import tools


def sales_scatter(df):
    fig = px.scatter(df, x="visits", y="sales", color="shop")
    fig.update_layout(title_text="Visits vs sales", titlefont=dict(size=18))
    return fig


def styled_axes(fig, x_title, y_title):
    fig.update_xaxes(title_text=x_title, titlefont=dict(size=12))
    fig.update_yaxes(title_text=y_title, titlefont=dict(size=12))
    return fig


def busy_hours(z):
    """Hour-by-weekday heat map (WebGL variant for big grids)."""
    return go.Figure(go.Heatmapgl(z=z, colorscale="Viridis"))


def shop_map(df):
    return px.scatter_mapbox(df, lat="lat", lon="lon", hover_name="shop", zoom=4)


def side_by_side(df):
    fig = tools.make_subplots(rows=1, cols=2)
    fig.append_trace(go.Bar(x=df["shop"], y=df["sales"]), 1, 1)
    fig.append_trace(go.Scatter(x=df["visits"], y=df["sales"], mode="markers"), 1, 2)
    return fig

